Visualization
To check the full results:

plots &lt;- cascade::prepare_tima_annotations(
  show_example = TRUE
) |&gt;
  cascade::plot_tima()
# cascade::prepare_tima_annotations(
#   annotations = list(
#     "yourExperiment1"="PathToYourTimaOutput1",
#     "yourExperiment2"="PathToYourTimaOutput2"
#     )
# ) |&gt;
#   cascade::plot_tima()


plots$histogram









plots$treemap






plots$sunburst





To compare annotated and predicted classes:

list(
  cascade::prepare_tima_annotations(
    show_example = TRUE
  )[[1]],
  cascade::prepare_tima_annotations(
    show_example = TRUE,
    predicted_classes = TRUE
  )[[1]]
) |&gt;
  data.table::rbindlist() |&gt;
  list() |&gt;
  cascade::plot_tima() |&gt;
  getElement("histogram")








To compare different filtering thresholds:

list(
  cascade::prepare_tima_annotations(
    show_example = TRUE
  )[[1]],
  cascade::prepare_tima_annotations(
    show_example = TRUE,
    min_score_biological = 0.2,
    min_score_final = 0.4
  )[[1]],
  cascade::prepare_tima_annotations(
    show_example = TRUE,
    min_score_initial = 0.2,
    min_score_biological = 0.2,
    min_score_chemical = 0.2,
    min_score_final = 0.4,
    min_matched_peaks_absolute = 6L,
    min_matched_peaks_percentage = 0.5,
    min_peaks = 10L
  )[[1]]
) |&gt;
  data.table::rbindlist() |&gt;
  list() |&gt;
  cascade::plot_tima() |&gt;
  getElement("histogram")








We hope you enjoyed using CASCADE and are pleased to hear from you!
For any remark or suggestion, please fill an issue or feel free to contact us directly.

Integrates peak-informed features across positive and/or negative modes with TIMA structural annotations and LOTUS taxonomic/literature metadata to produce both an interactive HTML table (with 2D chemical structure depictions via CDK Depict) and a tab-separated summary table.



generate_tables(
  annotations = NULL,
  file_negative = NULL,
  file_positive = NULL,
  min_confidence = 0.4,
  show_example = FALSE,
  export_csv = TRUE,
  export_html = TRUE,
  export_dir = "data/processed",
  export_name = "cascade_table"
)







annotations


Path to TIMA annotations .tsv file (optional when show_example = TRUE).




file_negative


Path to negative-mode informed features .tsv file (optional).




file_positive


Path to positive-mode informed features .tsv file (optional when show_example = TRUE).




min_confidence


Minimum final annotation confidence score. Default is 0.4.




show_example


Logical; use bundled example data. Default is FALSE.




export_csv


Logical; export .tsv summary table. Default is TRUE.




export_html


Logical; export .html interactive gt table. Default is TRUE.




export_dir


Directory where output files are written. Default is “data/processed”.




export_name


Base filename (without extension) for exported tables. Default is “cascade_table”.






A named list with two elements:


pretty_table: A gt_tbl interactive table object.


csv_table: A data.table containing the formatted summary rows.






library("cascade")


old_wd &lt;- setwd(tempdir())
generate_tables(show_example = TRUE, export_csv = FALSE, export_html = FALSE)

